<?php

namespace App\Helpers;

use Illuminate\Support\Facades\Route;

class MenuHelper
{
    /**
     * Buat satu item menu. Kalau route belum ada, item dilewati (null)
     * sehingga sidebar tidak error sebelum fitur-nya selesai dibuat.
     */
    private static function item(string $icon, string $name, string $routeName): ?array
    {
        if (! Route::has($routeName)) {
            return null;
        }

        return [
            'icon' => $icon,
            'name' => $name,
            'path' => route($routeName, [], false), // path relatif, mis. /penjual/products
        ];
    }

    public static function getPembeliItems(): array
    {
        return array_values(array_filter([
            self::item('dashboard', 'Dashboard', 'pembeli.dashboard'),
            self::item('tables', 'Katalog Produk', 'pembeli.catalog.index'),
            self::item('ecommerce', 'Keranjang', 'pembeli.cart.index'),
            self::item('task', 'Pesanan Saya', 'pembeli.orders.index'),
        ]));
    }

    public static function getPenjualItems(): array
    {
        return array_values(array_filter([
            self::item('dashboard', 'Dashboard', 'penjual.dashboard'),
            self::item('ui-elements', 'Kategori', 'penjual.categories.index'),
            self::item('ecommerce', 'Produk Saya', 'penjual.products.index'),
            self::item('task', 'Pesanan', 'penjual.orders.index'),
            self::item('forms', 'Pembayaran', 'penjual.payments.index'),
        ]));
    }

    public static function getMenuGroups(): array
    {
        $user = auth()->user();

        if ($user && $user->isPenjual()) {
            return [
                ['title' => 'Toko', 'items' => self::getPenjualItems()],
            ];
        }

        return [
            ['title' => 'Belanja', 'items' => self::getPembeliItems()],
        ];
    }

    public static function isActive($path)
    {
        return request()->is(ltrim($path, '/'));
    }

